from service import checkout

def submit_order(item, quantity):
    return checkout(item, quantity)

from repository import save_order

def checkout(item, quantity):
    if quantity <= 0:
        raise ValueError("quantity must be positive")
    order = {"item": item, "quantity": quantity}
    return save_order(order)

orders = []

def save_order(order):
    orders.append(order)
    return len(orders)
